(function(){
  function cls(n){ return Java.loadClass(n); }
  var BR = cls("net.minecraft.core.registries.BuiltInRegistries");
  var State = cls("com.merlinkitsune.astral_dice.shop.ChipShopState");
  var Opener = cls("com.merlinkitsune.astral_dice.shop.ChipShopOpener");
  var player = AutoJS.players()[0];
  var out = {};
  player.closeContainer();
  State.store(player, State.EMPTY);
  out.denyBeforeOpen = -999;
  Opener.open(player);
  var m = player.containerMenu;
  out.menuClass = String(m);
  out.menuIsShop = out.menuClass.indexOf("ChipShopMenu") >= 0;
  if (!out.menuIsShop) { out.abort = true; return out; }
  out.abort = false;
  out.price = m.price();
  out.remainingRefreshes = m.remainingRefreshes();
  out.totalRefreshes = m.totalRefreshes();
  out.denyReason = m.denyReason();
  out.slotsSize = m.slots.size();
  var ids = [], tiers = [], nonEmpty = 0;
  for (var i = 0; i < 3; i++) {
    var st = m.offerStack(i);
    if (st != null && !st.isEmpty()) {
      nonEmpty++;
      ids.push(String(BR.ITEM.getKey(st.getItem())));
    } else { ids.push(""); }
    tiers.push(m.offerTier(i));
  }
  out.offerIds = ids;
  out.offerTiers = tiers;
  out.offersNonEmpty = nonEmpty;
  var key = String(m.offersKey());
  out.offersKey = key;
  out.offersKeyNonEmpty = (key.length > 0 && key !== "-");
  var st = State.get(player);
  out.stateInitialized = st.initialized();
  out.statePrice = st.price();
  out.statePurchased = st.purchasedCount();
  out.stateRefreshes = st.refreshesLeft();
  player.closeContainer();
  State.store(player, State.EMPTY);
  out.teardownRefreshes = State.get(player).offers().size();
  return out;
})()
